// The first card with a full owner address, preferring one whose skills include skill_hint.
const want = ($('Looking for').first().json.skill_hint || '').toLowerCase();
const cards = $('Cards').first().json.cards || [];
const ok = cards.filter((c) => /^0x[0-9a-fA-F]{40}$/.test(c.owner || ''));
const pick = (want && ok.find((c) => (c.skills || []).some((s) => String(s).toLowerCase().includes(want)))) || ok[0];
if (!pick) throw new Error('no card with an owner address came back; widen the filters in Looking for');
return [{ json: { address: pick.owner, name: pick.name, kind: pick.kind, skills: pick.skills, endpoint: pick.endpoint || null, chain: pick.chainId, agent_id: pick.agentId || null, cards_seen: cards.length } }];

const cap = $('Capabilities').first().json, sk = $('Skills').first().json, st = $('Standards').first().json;
const cards = $('Cards').first().json, m = $('Market').first().json, p = $('Pick a provider').first().json, r = $json;
return [{ json: {
  capabilities: { templates: (cap.templates || {}).count ?? null, nodes: (cap.nodes || {}).count ?? null, skills_total: cap.skillsTotal ?? null },
  top_skills: (sk.skills || []).slice(0, 5).map((s) => `${s.tag} (${s.templates} templates, ${s.nodes} nodes)`),
  standards: (st.deployments || []).slice(0, 6).map((d) => `${d.standard} ${d.role} on ${d.chain}: ${d.address}`),
  cards: { matching: cards.matching ?? null, returned: cards.returned ?? null },
  market: { usdc_24h: m.usdc_24h, completion_rate: m.completion_rate, providers: m.provider_count, observed_jobs: m.observed_jobs },
  provider: p,
  reputation: { address: r.address, known: r.known, as_provider: r.as_provider, as_client: r.as_client, first_seen: r.first_seen, last_seen: r.last_seen, note: r.note },
} }];
